#include <iostream>
#include <string>
#include "../include/tsl/hopscotch_map.h"

int main(int argc, char* argv[]) {
    int count = 11;
    if (argc > 1 && std::string(argv[1]) == "--a") {
        count = std::stoi(argv[2]);
    }

    tsl::hopscotch_map<int, int> map;
    for (int i = 0; i < count; i++) {
        map.insert({i, i * 9});
    }

    std::cout << map.load_factor() << " ";
    map.max_load_factor(0.5);
    map.rehash(0);
    std::cout << map.load_factor() << std::endl;

    return 0;
}


/*
==============================
 TEST CASE EXAMPLES (Top 5)
==============================
--- Example 1 ---
Input Args: {}
Program Output: 0.6875 0.34375

--- Example 2 ---
Input Args: {"arg1": "--b"}
Program Output: 0.6875 0.34375

--- Example 3 ---
Input Args: {"arg1": "--A"}
Program Output: 0.6875 0.34375

--- Example 4 ---
Input Args: {"arg1": "--a", "arg2": "0"}
Program Output: 0 0

--- Example 5 ---
Input Args: {"arg1": "--a", "arg2": "1"}
Program Output: 0.5 0.5

