#!/bin/sh
# Differential test: run the Rust port and the reference C++ binary side by side
# and compare stdout, stderr, and exit status byte for byte.
#
#   tools/difftest.sh [path-to-cpp-binary]
#
# Defaults to the binary shipped with the dataset. Counts above a few million are
# skipped: both programs allocate a bucket per element, so beyond that the test
# measures the allocator rather than the arithmetic.

set -eu

CPP="${1:-/workspace/dataset/test11_executable}"
HERE="$(CDPATH='' cd -- "$(dirname -- "$0")/.." && pwd)"
RUST="$HERE/test11"

[ -x "$CPP" ] || { echo "reference binary not found: $CPP" >&2; exit 2; }
[ -x "$RUST" ] || {
    echo "build first: (cd $HERE && rustc --edition 2021 -O test11.rs -o test11)" >&2
    exit 2
}

CPP_ERR=$(mktemp)
RUST_ERR=$(mktemp)
trap 'rm -f "$CPP_ERR" "$RUST_ERR"' EXIT

checked=0
failed=0

compare() {
    # The assignments sit inside `if` so a non-zero exit does not trip `set -e`.
    # The extra 2>/dev/null suppresses the shell's own "Aborted" notice for the
    # cases where both programs are supposed to die from SIGABRT.
    if cpp_out=$(timeout 60 "$CPP" "$@" 2>"$CPP_ERR") 2>/dev/null; then
        cpp_rc=0
    else
        cpp_rc=$?
    fi
    if rust_out=$(timeout 60 "$RUST" "$@" 2>"$RUST_ERR") 2>/dev/null; then
        rust_rc=0
    else
        rust_rc=$?
    fi

    checked=$((checked + 1))
    if [ "$cpp_out" = "$rust_out" ] && [ "$cpp_rc" = "$rust_rc" ] &&
        cmp -s "$CPP_ERR" "$RUST_ERR"; then
        return 0
    fi

    failed=$((failed + 1))
    echo "MISMATCH args: $*"
    echo "  cpp  rc=$cpp_rc out=[$cpp_out] err=[$(cat "$CPP_ERR")]"
    echo "  rust rc=$rust_rc out=[$rust_out] err=[$(cat "$RUST_ERR")]"
}

echo "== default and non-matching flags =="
compare
for flag in --b --A -a '' '--a ' ' --a' '--a=5' --aa; do compare "$flag"; done
compare --b abc

echo "== every count from 0 to 1200 =="
i=0
while [ "$i" -le 1200 ]; do
    compare --a "$i"
    i=$((i + 1))
done

echo "== growth boundaries: trunc(bucket_count * 0.9) and its neighbours =="
k=1
while [ "$k" -le 22 ]; do
    bc=$((1 << k))
    thr=$(((bc * 9) / 10))
    for n in $((thr - 1)) "$thr" $((thr + 1)) $((bc - 1)) "$bc" $((bc + 1)); do
        if [ "$n" -ge 0 ] && [ "$n" -le 3000000 ]; then
            compare --a "$n"
        fi
    done
    k=$((k + 1))
done
for n in 10000 100000 999999 1000000 2500000; do compare --a "$n"; done

echo "== std::stoi parsing, including every throwing case =="
for arg in 007 ' 12' 12abc 3.9 +7 0x10 -5 -0 \
    0000000000000000000000000000012 2147483648 -2147483648 -2147483649 \
    9223372036854775808 99999999999999999999 \
    999999999999999999999999999999999999 abc '' '   ' - + ' - 5'; do
    compare --a "$arg"
done
compare --a "$(printf '  \t\n\v\f\r +42xyz')"
compare --a 15 extra

echo "== the missing-argv[2] abort path =="
compare --a

echo
echo "compared $checked invocations, $failed mismatches"
[ "$failed" -eq 0 ]
