/* Differential fuzzer: run the C++ reference and the Rust port with identical
 * argv, compare stdout, stderr and wait-status byte for byte.
 *
 *   gcc -O2 -o dfuzz dfuzz.c
 *   ./dfuzz <mode> <iters> <seed>
 *
 * modes: counts argv1 argv2 argc all
 */
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <errno.h>

static const char *CPP = "/workspace/dataset/test11_executable";
static const char *RUST = "/output/test11";

static unsigned long long S;
static unsigned long long rnd(void) {
    /* splitmix64 */
    unsigned long long z = (S += 0x9E3779B97F4A7C15ULL);
    z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9ULL;
    z = (z ^ (z >> 27)) * 0x94D049BB133111EBULL;
    return z ^ (z >> 31);
}
static unsigned long long rr(unsigned long long n) { return n ? rnd() % n : 0; }

#define CAP (1 << 20)

struct res {
    char out[CAP];
    size_t outn;
    char err[CAP];
    size_t errn;
    int status; /* raw wait status */
    int failed; /* harness failure */
};

static void drain(int fd, char *buf, size_t *n, size_t cap) {
    /* not used: we read both pipes in a select-free loop below */
    (void)fd; (void)buf; (void)n; (void)cap;
}

static int run(const char *exe, char *const *argv, struct res *r) {
    int op[2], ep[2];
    memset(r, 0, sizeof *r);
    if (pipe(op) || pipe(ep)) return -1;
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid == 0) {
        dup2(op[1], 1);
        dup2(ep[1], 2);
        close(op[0]); close(op[1]); close(ep[0]); close(ep[1]);
        execv(exe, argv);
        _exit(127);
    }
    close(op[1]); close(ep[1]);
    int done_o = 0, done_e = 0;
    while (!done_o || !done_e) {
        char tmp[65536];
        if (!done_o) {
            ssize_t k = read(op[0], tmp, sizeof tmp);
            if (k > 0) {
                if (r->outn + (size_t)k < CAP) { memcpy(r->out + r->outn, tmp, k); r->outn += k; }
            } else if (k == 0) done_o = 1;
            else if (errno != EINTR) done_o = 1;
        }
        if (!done_e) {
            ssize_t k = read(ep[0], tmp, sizeof tmp);
            if (k > 0) {
                if (r->errn + (size_t)k < CAP) { memcpy(r->err + r->errn, tmp, k); r->errn += k; }
            } else if (k == 0) done_e = 1;
            else if (errno != EINTR) done_e = 1;
        }
    }
    close(op[0]); close(ep[0]);
    int st = 0;
    while (waitpid(pid, &st, 0) < 0 && errno == EINTR) {}
    r->status = st;
    return 0;
}

static void show(const char *s, size_t n) {
    for (size_t i = 0; i < n; i++) {
        unsigned char c = (unsigned char)s[i];
        if (c == '\n') fputs("\\n", stdout);
        else if (c == '\t') fputs("\\t", stdout);
        else if (c < 32 || c > 126) printf("\\x%02x", c);
        else putchar(c);
    }
}

static long long compared = 0, mismatches = 0;

static void cmp_case(int nargs, char **args) {
    /* build argv arrays: argv[0] differs (path) but the program never reads it */
    char *av1[16], *av2[16];
    int i;
    av1[0] = (char *)CPP;
    av2[0] = (char *)RUST;
    for (i = 0; i < nargs; i++) { av1[i + 1] = args[i]; av2[i + 1] = args[i]; }
    av1[nargs + 1] = NULL; av2[nargs + 1] = NULL;

    struct res a, b;
    if (run(CPP, av1, &a) || run(RUST, av2, &b)) { printf("HARNESS FAIL\n"); exit(2); }
    compared++;
    int same = a.outn == b.outn && memcmp(a.out, b.out, a.outn) == 0 &&
               a.errn == b.errn && memcmp(a.err, b.err, a.errn) == 0 &&
               a.status == b.status;
    if (same) return;
    mismatches++;
    printf("MISMATCH nargs=%d argv=[", nargs);
    for (i = 0; i < nargs; i++) { if (i) putchar('|'); show(args[i], strlen(args[i])); }
    printf("]\n");
    printf("  cpp  st=0x%04x out=<", a.status); show(a.out, a.outn);
    printf("> err=<"); show(a.err, a.errn); printf(">\n");
    printf("  rust st=0x%04x out=<", b.status); show(b.out, b.outn);
    printf("> err=<"); show(b.err, b.errn); printf(">\n");
    fflush(stdout);
    if (mismatches > 60) { printf("too many mismatches, stopping\n"); exit(1); }
}

static void cmp_count(long long n) {
    char buf[64];
    snprintf(buf, sizeof buf, "%lld", n);
    char *args[2] = { "--a", buf };
    cmp_case(2, args);
}

/* ------------------------------------------------------------------ counts */
static void mode_counts(long long iters) {
    long long thr[64]; int nt = 0;
    for (int k = 0; k <= 22; k++) {
        long long bc = 1LL << k;
        /* trunc((float)bc * 0.9f) */
        float f = (float)bc * 0.9f;
        thr[nt++] = (long long)f;
    }
    for (long long it = 0; it < iters; it++) {
        unsigned long long pick = rr(100);
        long long n;
        if (pick < 30) {
            n = (long long)rr(200);                 /* tiny */
        } else if (pick < 50) {
            n = (long long)rr(4000);
        } else if (pick < 75) {
            /* near a growth boundary */
            long long base = thr[rr((unsigned)nt)];
            n = base + (long long)rr(9) - 4;
        } else if (pick < 85) {
            /* near a power of two */
            long long base = 1LL << rr(23);
            n = base + (long long)rr(9) - 4;
        } else if (pick < 97) {
            n = (long long)rr(3000001);
        } else {
            /* negatives and huge */
            long long r = (long long)rr(4);
            if (r == 0) n = -(long long)rr(1000);
            else if (r == 1) n = 2147483647LL - (long long)rr(5);
            else if (r == 2) n = -2147483648LL + (long long)rr(5);
            else n = (long long)rr(3000001);
        }
        if (n < -2147483648LL) n = -2147483648LL;
        if (n > 2147483647LL) n = 2147483647LL;
        cmp_count(n);
    }
}

/* ------------------------------------------------------------- random text */
static const char *ODD[] = {
    "--a", "--a ", " --a", "--a\t", "\t--a", "--a\n", "--A", "--b", "-a", "--aa",
    "--", "-", "", "=", "--a=", "--a=5", "--a=--a", "a--", "--\xc3\xa1",
    "\xe2\x80\x93\xe2\x80\x93a", "--\xef\xbd\x81", "--a\xc2\xa0", "\xc2\xa0--a",
    "--A ", "--a--a", "\xff\xfe", "\x01\x02", "--a\x7f", "--\x61", "-\x2d\x61",
    "--a=0", "-=a", "a", "A", "--a\r", "\r--a", "--a\v", "--a\f",
};
enum { NODD = sizeof ODD / sizeof ODD[0] };

static const char *NUMS[] = {
    "", " ", "  ", "\t", "\n", "\v", "\f", "\r", " \t\n\v\f\r", "0", "-0", "+0",
    "1", "-1", "+1", "007", "0x10", "0X1f", "010", "3.9", "-3.9", "1e3", "1E3",
    "12abc", "abc", "abc12", "-", "+", "--5", "++5", " - 5", "- 5", "+ 5",
    "2147483647", "2147483648", "-2147483648", "-2147483649", "2147483646",
    "4294967295", "4294967296", "9223372036854775807", "9223372036854775808",
    "-9223372036854775808", "-9223372036854775809", "99999999999999999999",
    "0000000000000000000000000000012", "-0000000000000000000000000000012",
    "  \t\n\v\f\r +42xyz", "\n\n\n42", "0b101", "inf", "INF", "nan", "NAN",
    "infinity", "0.0", ".5", "1,000", "1_000", "1 2", "42 ", "42\n", "42\t",
    "\x0b42", "\x0c42", "\r42", "\xc2\xa042", "\xef\xbb\xbf42", "\xc2\xb912",
    "\xd9\xa1\xd9\xa2", "\xef\xbc\x91\xef\xbc\x92", "'42'", "\"42\"", "(42)",
    "0777", "0o17", "#42", "42#", "@42", "~42", "42.", ".", "..", "1/2",
    "\x80\x81", "\xff", "\x7f", "\x01", "\x1f42", "1\x0042",
};
enum { NNUMS = sizeof NUMS / sizeof NUMS[0] };

static void rand_str(char *buf, size_t cap, int flavour) {
    size_t len;
    switch (flavour) {
    case 0: len = rr(6); break;
    case 1: len = rr(24); break;
    case 2: len = 1 + rr(200); break;
    case 3: len = 1 + rr(cap - 2); break;   /* very long */
    default: len = rr(12); break;
    }
    if (len > cap - 1) len = cap - 1;
    for (size_t i = 0; i < len; i++) {
        unsigned c;
        unsigned long long k = rr(100);
        if (k < 40) {
            /* digits and signs and spaces: interesting for stoi */
            static const char pool[] = "0123456789+- \t\n\v\f\r";
            c = (unsigned char)pool[rr(sizeof pool - 1)];
        } else if (k < 60) {
            static const char pool[] = "abcdefABCDEFxX.,_=-";
            c = (unsigned char)pool[rr(sizeof pool - 1)];
        } else if (k < 90) {
            c = 1 + rr(255);            /* any non-NUL byte */
        } else {
            c = 32 + rr(95);            /* printable ASCII */
        }
        if (c == 0) c = '0';
        buf[i] = (char)c;
    }
    buf[len] = 0;
}

static void mode_argv1(long long iters) {
    char b1[8192], b2[64];
    for (long long it = 0; it < iters; it++) {
        char *args[3];
        int nargs;
        if (rr(2)) {
            strcpy(b1, ODD[rr(NODD)]);
        } else {
            rand_str(b1, (rr(20) == 0) ? sizeof b1 : 256, (int)rr(4));
        }
        args[0] = b1;
        snprintf(b2, sizeof b2, "%llu", (unsigned long long)rr(300));
        args[1] = b2;
        nargs = 1 + (int)rr(2);
        cmp_case(nargs, args);
    }
}

static void mode_argv2(long long iters) {
    char b2[8192];
    for (long long it = 0; it < iters; it++) {
        char *args[3];
        unsigned long long k = rr(3);
        if (k == 0) strcpy(b2, NUMS[rr(NNUMS)]);
        else rand_str(b2, (rr(30) == 0) ? sizeof b2 : 128, (int)rr(4));
        args[0] = "--a";
        args[1] = b2;
        int nargs = 2 + (int)rr(2);
        args[2] = "junk";
        cmp_case(nargs, args);
    }
}

static void mode_argc(long long iters) {
    char bufs[10][32];
    char *args[10];
    for (long long it = 0; it < iters; it++) {
